Maintain frequency differences between the current window and p, deleting zero counts. An empty map means the window is an anagram; scanning left to right returns indices in ascending order.

```javascript
function solve(s, p) {
  const m = p.length;
  const result = [];
  if (m > s.length) return result;

  const diff = new Map();

  function adjust(char, delta) {
    const count = (diff.get(char) || 0) + delta;
    if (count === 0) diff.delete(char);
    else diff.set(char, count);
  }

  for (let i = 0; i < m; i++) {
    adjust(p[i], -1);
  }

  for (let i = 0; i < s.length; i++) {
    adjust(s[i], 1);
    if (i >= m) adjust(s[i - m], -1);

    if (i >= m - 1 && diff.size === 0) {
      result.push(i - m + 1);
    }
  }

  return result;
}
```

Call solve(s, p) directly with nonempty p. Expected time is O(s.length + p.length), assuming constant-time Map operations; auxiliary space is O(k), where k is the number of distinct characters in p and the active window, plus O(r) for the returned indices.

