Expand around every character and gap, keeping the longest palindrome and choosing the earliest start on ties.

```javascript
function solve(s) {
  let bestStart = 0;
  let bestLength = 0;

  function expand(left, right) {
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      const length = right - left + 1;
      if (
        length > bestLength ||
        (length === bestLength && left < bestStart)
      ) {
        bestStart = left;
        bestLength = length;
      }
      left--;
      right++;
    }
  }

  for (let i = 0; i < s.length; i++) {
    expand(i, i);
    expand(i, i + 1);
  }

  return s.slice(bestStart, bestStart + bestLength);
}
```

Call solve(s) directly. Empty input returns "". Time: O(n²); auxiliary space: O(1), excluding the returned substring.

